stcd AS (   -- SQL Server's ST-CD-xxx placeholder codes (all 'NA')
  SELECT 'ST-CD-' || TRIM(VALUE) AS ST_CD, 'NA' AS ST_STAT, 'NA' AS ST_TYP
  FROM TABLE(SPLIT_TO_TABLE('004,009,010,013,018,020,022,023,025,026,027,028,030,031,032,033,034,035,036,037,057,064,065,067,068,074,075,076,077,078,079,080,081,082,083,084,086,087,088,089,090,091,092,093,094,095,096,097,098,099,104,111,118,119,120,125,144,250,251,252,253,256,258,259,260,263,265,267,268,269,270,271,272,273', ','))
  UNION ALL
  SELECT 'ST-CD-' || LPAD(SEQ4() + 157, 3, '0'), 'NA', 'NA' FROM TABLE(GENERATOR(ROWCOUNT => 92))   -- 157..248
),
sqls AS (SELECT * FROM sqls_main UNION ALL SELECT * FROM stcd),
snow AS (
    SELECT TRIM(ST_CD) ST_CD, TRIM(ST_STAT) ST_STAT, TRIM(ST_TYP) ST_TYP
    FROM V2RETAIL.AKS_SILVER.SLV_MIS_STORE_MASTER
)
SELECT COALESCE(q.ST_CD, f.ST_CD) AS ST_CD,
       q.ST_STAT AS SQLS_STAT, f.ST_STAT AS SNOW_STAT,
       q.ST_TYP  AS SQLS_TYP,  f.ST_TYP  AS SNOW_TYP,
       CASE WHEN q.ST_CD IS NULL THEN 'ONLY SNOWFLAKE'
            WHEN f.ST_CD IS NULL THEN 'ONLY SQL SERVER'
            WHEN q.ST_STAT IS DISTINCT FROM f.ST_STAT THEN 'STATUS DIFFERS'
            ELSE 'TYPE DIFFERS' END AS ISSUE
FROM sqls q
FULL JOIN snow f ON f.ST_CD = q.ST_CD
WHERE q.ST_CD IS NULL OR f.ST_CD IS NULL
   OR q.ST_STAT IS DISTINCT FROM f.ST_STAT
   OR q.ST_TYP  IS DISTINCT FROM f.ST_TYP
ORDER BY ISSUE DESC, ST_CD;


-- 2. Sales/stock of the stores whose status differs (from the staging table, last 31 days)
SELECT STORE_CODE, MIN(DATES) FIRST_DT, MAX(DATES) LAST_DT,
       ROUND(SUM(IFF(PARTICULARS_NAME = 'SALE_V', PARTICULARS_VALUE, 0))) AS SALE_V_31D,
       ROUND(SUM(IFF(PARTICULARS_NAME = 'STK_Q'
                     AND DATES = (SELECT MAX(DATES) FROM V2RETAIL.SILVER.TREND_KPI_DATA),
                     PARTICULARS_VALUE, 0)))                     AS STK_Q_LAST_DAY
FROM V2RETAIL.SILVER.TREND_KPI_DATA
WHERE STORE_CODE IN ('HB73', 'HJ30', 'HW55', 'HX13', 'HX14')
GROUP BY STORE_CODE
ORDER BY STORE_CODE;
